DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.reports_north_star(date,date,jsonb,timestamptz)'::regprocedure); d:=replace(d,'SELECT jsonb_build_object(''total'',count(*)','SELECT jsonb_build_object(''rows'',COALESCE(jsonb_agg(jsonb_build_object(''relationship_id'',id,''talent_user_id'',talent_user_id,''talent_active'',talent_active,''agency_active'',agency_active) ORDER BY id),''[]''::jsonb),''total'',count(*)'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.reports_evidence_page(_from date,_to date,_filters jsonb,_dataset text,_limit integer DEFAULT 25,_offset integer DEFAULT 0,_as_of timestamptz DEFAULT now(),_download boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE result jsonb; BEGIN
IF NOT public.reports_can('view_reports') OR (_download AND NOT public.reports_can('download_raw_data')) THEN RAISE EXCEPTION 'REPORT_ACCESS_DENIED: Your Reports role does not allow this action.' USING ERRCODE='42501'; END IF;
IF _dataset NOT IN ('sign_in_events','relationships') OR _from IS NULL OR _to IS NULL OR _from>_to OR _limit NOT BETWEEN 1 AND 200 OR _offset<0 OR _as_of IS NULL THEN RAISE EXCEPTION 'REPORT_FILTER_INVALID: Choose valid report filters.'; END IF;
PERFORM public.reports_people_page(_from,_to,_filters,1,0,'name','asc',false,_as_of,false);
IF _dataset='relationships' THEN
WITH evidence AS MATERIALIZED(SELECT r FROM jsonb_array_elements(public.reports_north_star(_from,_to,_filters,_as_of)->'rows') r), page AS(SELECT r FROM evidence ORDER BY r->>'relationship_id' LIMIT _limit OFFSET _offset)
SELECT jsonb_build_object('columns',jsonb_build_array('Relationship ID','Talent user ID','Talent activity','Agency relationship activity','Engaged'),'total',(SELECT count(*) FROM evidence),'rows',COALESCE((SELECT jsonb_agg(jsonb_build_array(r->>'relationship_id',r->>'talent_user_id',CASE WHEN (r->>'talent_active')::boolean THEN 'Yes' ELSE 'No' END,CASE WHEN (r->>'agency_active')::boolean THEN 'Yes' ELSE 'No' END,CASE WHEN (r->>'talent_active')::boolean AND (r->>'agency_active')::boolean THEN 'Yes' ELSE 'No' END)) FROM page),'[]'::jsonb)) INTO result;
ELSE
WITH bounds AS(SELECT _from::timestamp AT TIME ZONE 'Africa/Johannesburg' start_at,LEAST((_to+1)::timestamp AT TIME ZONE 'Africa/Johannesburg',_as_of,now()) end_at), people AS MATERIALIZED(SELECT r FROM public.reports_people_rows(_from,_to,_filters,_as_of) r), evidence AS MATERIALIZED(
SELECT e.id::text id,p.r->>'person_id' person_id,p.r->>'account_type' typ,e.created_at ts,'Completed sign-in' label FROM public.talent_audit_log e JOIN people p ON p.r->>'person_id'=e.actor_id::text CROSS JOIN bounds b WHERE e.action='login' AND e.created_at>=b.start_at AND e.created_at<b.end_at
UNION ALL SELECT e.id::text,p.r->>'person_id','trusted_contact',e.created_at,'Successful access-code visit' FROM public.loved_one_share_access_events e JOIN public.loved_one_shares s ON s.id=e.share_id JOIN public.talent_profiles t ON t.id=s.talent_id JOIN people p ON p.r->>'person_id'='recipient:'||md5(lower(btrim(s.loved_one_email))) CROSS JOIN bounds b WHERE e.event='successful_code' AND e.created_at>=b.start_at AND e.created_at<b.end_at AND EXISTS(SELECT 1 FROM public.reports_people_rows(_from,_to,jsonb_set(jsonb_set(_filters,'{account_type}','"talent"'),'{people}','[]'),_as_of) owner WHERE owner->>'person_id'=t.user_id::text)
), page AS(SELECT * FROM evidence ORDER BY ts,id LIMIT _limit OFFSET _offset)
SELECT jsonb_build_object('columns',jsonb_build_array('Event ID','Person ID','Account type','Occurred at (UTC)','Event'),'total',(SELECT count(*) FROM evidence),'rows',COALESCE((SELECT jsonb_agg(jsonb_build_array(id,person_id,typ,ts,label)) FROM page),'[]'::jsonb)) INTO result;
END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reports_evidence_page(date,date,jsonb,text,integer,integer,timestamptz,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.reports_evidence_page(date,date,jsonb,text,integer,integer,timestamptz,boolean) TO authenticated;